    const expected = [todos[1], todos[5], todos[0], todos[3]];
    expect(list(todos, { includeDone: false })).toBe(formatList(expected));
  });

  it("does not mutate the input array", () => {
    const copy = [...todos];
    list(todos);
    expect(todos).toEqual(copy);
    todos.forEach((t, i) => expect(t).toBe(copy[i]));
  });
});

